SELECT auction, CAST(dateTime AS DATE) AS day, count(*) AS total_bids, count(*) FILTER (WHERE price < 10000) AS rank1_bids, min(price) AS min_price, max(price) AS max_price, avg(price) AS avg_price, sum(price) AS sum_price FROM bid WHERE dateTime >= TIMESTAMP '2015-07-16 00:00:00' GROUP BY auction, day ORDER BY total_bids DESC, auction, day LIMIT 100;
